367		assertDeliveryMatches(t, d2, want, "second delivery after first tampered")
368	
369		// 再次取包仍是创建时固化的原内容与原摘要、原状态。
370		d3, err := f.s.FetchPackage(rcv, x.ID)
371		if err != nil {
372			t.Fatal(err)
373		}
374		assertDeliveryMatches(t, d3, want, "re-fetch after tampering held delivery")
375	
376		// 内部使用者查看原交换：原内容与摘要不受接收方本地修改影响。
377		g, err := f.s.GetExchange(doc, f.pid, x.ID)
378		if err != nil {
379			t.Fatal(err)
380		}
381		assertExchangeMatches(t, g, x, "internal view after receiver tampered delivery")
382	
383		if got := len(mustAudit(t, f.s, f.pid)); got != auditBefore {
384			t.Fatalf("local package tamper changed audit count: before=%d after=%d", auditBefore, got)
385		}
386	}
387	
388	// ---- 本地改过摘要再交回执：ErrConflict、保持待回执、无回执审计；
389	//      使用原摘要仍可正常登记 ----
390	
391	func TestTamperedDigestReceiptConflictsButOriginalStillWorks(t *testing.T) {
392		f := setupExchange(t)
393		x, err := f.s.CreateExchange(doc, f.pid, rcv.ID, f.auth.ID,
394			[]ID{f.diag, f.ord}, "req-iso-digest")
395		if err != nil {
396			t.Fatal(err)
397		}
398		originalDigest := x.Digest
399	
400		d, err := f.s.FetchPackage(rcv, x.ID)
401		if err != nil {
402			t.Fatal(err)
403		}
404		// 调用方在手中把摘要改成另一个值，并顺手改了包内容。
405		d.Digest = "caller-local-digest-value"
406		d.Package.Records[0].Content = "本地改过的内容"
407	
408		if receiptAuditCount(t, f.s, f.pid) != 0 {
409			t.Fatal("unexpected receipt audit before any registration")
410		}
411	
412		// 用改过的摘要登记：ErrConflict。
413		if _, err := f.s.SubmitReceipt(rcv, x.ID, d.Digest, ReceiptAccepted, ""); !errors.Is(err, ErrConflict) {
414			t.Fatalf("submit with tampered digest err = %v, want ErrConflict", err)
415		}
416	
417		// 原交换继续保持待回执、无回执，摘要与包内容不变。
418		g, err := f.s.GetExchange(doc, f.pid, x.ID)
