430		// 再次取包仍给出原摘要与待回执状态。
431		d2, err := f.s.FetchPackage(rcv, x.ID)
432		if err != nil {
433			t.Fatal(err)
434		}
435		if d2.Digest != originalDigest || d2.Status != ExchangePending {
436			t.Fatalf("re-fetch after conflict: digest=%q status=%q", d2.Digest, d2.Status)
437		}
438	
439		// 使用原摘要正常登记仍应成功——先前的本地修改没有让登记能力失效。
440		conf, err := f.s.SubmitReceipt(rcv, x.ID, originalDigest, ReceiptRejected, "接收方核对后真实拒绝")
441		if err != nil {
442			t.Fatalf("submit with original digest after local tamper: %v", err)
443		}
444		if conf.Status != ExchangeRejected || conf.Outcome != ReceiptRejected {
445			t.Fatalf("bad confirmation: %+v", conf)
446		}
447		g2, err := f.s.GetExchange(doc, f.pid, x.ID)
448		if err != nil {
449			t.Fatal(err)
450		}
451		if g2.Status != ExchangeRejected || g2.Receipt == nil ||
452			g2.Receipt.Outcome != ReceiptRejected || g2.Receipt.Reason != "接收方核对后真实拒绝" {
453			t.Fatalf("genuine receipt not stored: %+v", g2)
454		}
455		if c := receiptAuditCount(t, f.s, f.pid); c != 1 {
456			t.Fatalf("receipt audits = %d, want 1", c)
457		}
458	}
