566		}
567		lst[0].Status = ExchangeAccepted
568		lst[0].Receipt = &Receipt{Outcome: ReceiptAccepted, RegisteredAt: time.Now()}
569	
570		g3, _ := f.s.GetExchange(doc, f.pid, x.ID)
571		if g3.Status != ExchangePending || g3.Receipt != nil {
572			t.Fatalf("fabricated receipt via list leaked into store: %+v", g3)
573		}
