142		if _, err := f.s.GrantSelective(doc, f.pid, rcv.ID, nil,
143			[]RecordSelection{sel(f.e1, Order, f.r1)}, st, en); !errors.Is(err, ErrInvalidArgument) {
144			t.Fatalf("category mismatch err = %v, want ErrInvalidArgument", err)
145		}
