483	// ---- 同一条授权在“接收方查阅”与“创建交换”中的覆盖含义必须一致 ----
484	//
485	// 两个功能共用同一套范围解释：任一记录要么两处都覆盖，要么两处都不覆盖；
486	// 限定范围不外溢、整类范围包含授权后生效记录、覆盖不串到其他就诊，这些结论
487	// 在查阅与打包两条路径上必须相同。
488	
489	func TestCoverageConsistentAcrossReadAndExchange(t *testing.T) {
490		f := setupSelective(t)
491	
492		// 同一条混合授权：整类覆盖 e1 医嘱；选定 e1 诊断 r1。
493		grant, err := f.s.GrantSelective(doc, f.pid, rcv.ID,
494			[]Scope{{EncounterID: f.e1, Category: Order}},
495			[]RecordSelection{sel(f.e1, Diagnosis, f.r1)},
496			f.start, f.end)
497		if err != nil {
498			t.Fatal(err)
499		}
500	
501		// 查阅：诊断只见明确选中的 r1，同类的 r2 不出现。
502		diag, err := f.s.Read(rcv, f.pid, f.e1, Diagnosis)
503		if err != nil {
504			t.Fatalf("read diagnosis: %v", err)
505		}
506		if ids := readRecordIDs(diag); len(ids) != 1 || !ids[f.r1] {
507			t.Fatalf("diagnosis read = %+v, want only selected r1", diag.Records)
508		}
509		// 查阅：整类医嘱见 r3。
510		ord, err := f.s.Read(rcv, f.pid, f.e1, Order)
511		if err != nil {
512			t.Fatalf("read order: %v", err)
513		}
514		if ids := readRecordIDs(ord); len(ids) != 1 || !ids[f.r3] {
515			t.Fatalf("order read = %+v, want whole-category r3", ord.Records)
516		}
517	
518		// 与查阅一致：r1、r3 各自由这条绑定授权打包成功；r2 两处都不覆盖。
519		packagable := func(rid ID) bool {
520			_, perr := f.s.CreateExchange(doc, f.pid, rcv.ID, grant.ID,
521				[]ID{rid}, "req-"+rid)
522			return perr == nil
523		}
524		if !packagable(f.r1) {
525			t.Fatal("selected r1 must be packageable by the bound grant")
526		}
527		if !packagable(f.r3) {
528			t.Fatal("whole-category r3 must be packageable by the bound grant")
529		}
530		if packagable(f.r2) {
531			t.Fatal("non-selected sibling r2 must not be packageable, matching read")
532		}
533	
534		// 授权建立后新增并生效：限定诊断不外溢，整类医嘱自然包含——
535		// 查阅与打包两条路径必须给出同一结论。
536		newDiag, _ := f.s.CreateDraft(doc, f.pid, f.e1, Diagnosis, "授权后诊断")
537		if _, err := f.s.ActivateRecord(doc, newDiag.ID); err != nil {
538			t.Fatal(err)
539		}
540		newOrder, _ := f.s.CreateDraft(doc, f.pid, f.e1, Order, "授权后医嘱")
541		if _, err := f.s.ActivateRecord(doc, newOrder.ID); err != nil {
542			t.Fatal(err)
543		}
544		diag, _ = f.s.Read(rcv, f.pid, f.e1, Diagnosis)
545		if ids := readRecordIDs(diag); ids[newDiag.ID] {
546			t.Fatalf("later diagnosis leaked into selected scope: %+v", diag.Records)
547		}
548		ord, _ = f.s.Read(rcv, f.pid, f.e1, Order)
549		if ids := readRecordIDs(ord); !ids[newOrder.ID] {
550			t.Fatalf("later order missing from whole scope: %+v", ord.Records)
551		}
552		if packagable(newDiag.ID) {
553			t.Fatal("later diagnosis must not be packageable under selected scope")
554		}
555		if !packagable(newOrder.ID) {
556			t.Fatal("later order must be packageable under whole scope")
557		}
558	
559		// 覆盖关系不串到其他就诊：e2 的诊断查阅被拒，也不能由本授权打包。
560		if _, err := f.s.Read(rcv, f.pid, f.e2, Diagnosis); !errors.Is(err, ErrAccessDenied) {
561			t.Fatalf("other encounter read err = %v, want ErrAccessDenied", err)
562		}
563		if packagable(f.e2rec) {
564			t.Fatal("record from another encounter must not be packageable")
565		}
566	}
567	
568	// ---- 重开恢复：限定记录、授权状态、历史交换保留 ----
569	
570	func TestSelectivePersistenceAcrossReopen(t *testing.T) {
571		dir := t.TempDir()
572		clk := &fakeClock{t: time.Date(2026, 5, 1, 8, 0, 0, 0, time.UTC)}
573		open := func() *Store {
574			s, err := Open(dir, WithClock(func() time.Time { return clk.t }))
575			if err != nil {
576				t.Fatalf("open: %v", err)
577			}
578			return s
579		}
580	
581		s := open()
582		p, _ := s.RegisterPatient(doc, "限定持久化患者")
583		e, _ := s.AddEncounter(doc, p.ID, time.Time{})
584		d1, _ := s.CreateDraft(doc, p.ID, e.ID, Diagnosis, "诊断1")
585		if _, err := s.ActivateRecord(doc, d1.ID); err != nil {
586			t.Fatal(err)
587		}
588		d2, _ := s.CreateDraft(doc, p.ID, e.ID, Diagnosis, "诊断2")
589		if _, err := s.ActivateRecord(doc, d2.ID); err != nil {
590			t.Fatal(err)
591		}
592		a, _ := s.GrantSelective(doc, p.ID, rcv.ID, nil,
593			[]RecordSelection{sel(e.ID, Diagnosis, d1.ID)},
594			clk.t.Add(-time.Hour), clk.t.Add(48*time.Hour))
595		x, err := s.CreateExchange(doc, p.ID, rcv.ID, a.ID, []ID{d1.ID}, "req-persist-sel")
596		if err != nil {
597			t.Fatal(err)
598		}
599		if err := s.Close(); err != nil {
600			t.Fatal(err)
601		}
602	
603		s2 := open()
604		t.Cleanup(func() { _ = s2.Close() })
605	
606		got, err := s2.GetAuthorization(doc, p.ID, a.ID)
607		if err != nil {
608			t.Fatalf("auth after reopen: %v", err)
609		}
610		if len(got.Scopes) != 0 || len(got.Selections) != 1 || got.Selections[0].RecordID != d1.ID {
611			t.Fatalf("limited scope not preserved: %+v", got)
612		}
613		// 仍只放行选中记录。
614		res, err := s2.Read(rcv, p.ID, e.ID, Diagnosis)
615		if err != nil || len(res.Records) != 1 || res.Records[0].RecordID != d1.ID {
616			t.Fatalf("read after reopen: %+v %v", res, err)
617		}
618		// 历史交换保留，同请求重试返回原交换。
619		retry, err := s2.CreateExchange(doc, p.ID, rcv.ID, a.ID, []ID{d1.ID}, "req-persist-sel")
620		if err != nil || retry.ID != x.ID {
621			t.Fatalf("retry after reopen: id=%q err=%v", retry.ID, err)
622		}
623		// 未选中记录仍不能借该授权打包。
624		if _, err := s2.CreateExchange(doc, p.ID, rcv.ID, a.ID, []ID{d2.ID}, "req-persist-sel-2"); !errors.Is(err, ErrAccessDenied) {
625			t.Fatalf("unselected package after reopen err = %v", err)
626		}
627	}
