374	// ---- 当前版本视图与历史列表彼此独立：只改一处，另一处不跟着变 ----
375	
376	func TestEncounterRecordsCurrentAndHistoryAreIndependent(t *testing.T) {
377		s, _ := newTestStore(t)
378		pid, e1 := setupPatientEncounter(t, s)
379		rid := mustCreateDraft(t, s, pid, e1, Diagnosis, "诊断第 1 版内容")
380		v1 := mustActivate(t, s, rid)
381		v2 := mustCorrect(t, s, rid, 1, "诊断第 2 版内容", "诊断更正原因")
382	
383		baseline, err := s.EncounterRecords(doc, pid, e1)
384		if err != nil {
385			t.Fatal(err)
386		}
387		want := snapshotHistories(baseline)
388	
389		// 只改手中结果的当前版本视图，历史列表中对应版本不得跟着变。
390		fresh, err := s.EncounterRecords(doc, pid, e1)
391		if err != nil {
392			t.Fatal(err)
393		}
394		hc := historiesByID(fresh)[rid]
395		origLast := hc.Versions[len(hc.Versions)-1] // 值快照
396		hc.CurrentVersion.ID = "ver_cv_only_local"
397		hc.CurrentVersion.Number = 999
398		hc.CurrentVersion.Content = "只改当前版本视图"
399		hc.CurrentVersion.PrevID = "ver_cv_only_local_prev"
400		hc.CurrentVersion.Reason = "只写在当前版本视图上的原因"
401		if got := hc.Versions[len(hc.Versions)-1]; got != origLast {
402			t.Fatalf("mutating CurrentVersion dragged the history entry with it:\n got=%+v\nwant=%+v", got, origLast)
403		}
404	
405		// 只改手中结果的历史列表（内容、原因、上一版本关系），当前版本视图不得跟着变。
406		fresh2, err := s.EncounterRecords(doc, pid, e1)
407		if err != nil {
408			t.Fatal(err)
409		}
410		hc2 := historiesByID(fresh2)[rid]
411		origCurrent := *hc2.CurrentVersion
412		last := &hc2.Versions[len(hc2.Versions)-1]
413		last.Content = "只改历史列表"
414		last.Reason = "只写在历史列表上的原因"
415		last.PrevID = "ver_hist_only_local_prev"
416		if *hc2.CurrentVersion != origCurrent {
417			t.Fatalf("mutating history list dragged CurrentVersion with it:\n got=%+v\nwant=%+v",
418				*hc2.CurrentVersion, origCurrent)
419		}
420	
421		// 两处本地改动后，重新读取的正式历史保持原值。
422		again, err := s.EncounterRecords(doc, pid, e1)
423		if err != nil {
424			t.Fatal(err)
425		}
426		assertHistoriesMatches(t, again, want, "official history after local current/history edits")
427		_ = v1
428		_ = v2
429	}
