152	// 与更正原因都会保留。新版本与审计事件一同原子落盘。
153	func (s *Store) CorrectRecord(actor Actor, recordID ID, expectedCurrentVersion int, content, reason string) (Version, error) {
154		if !actor.valid() || !actor.IsInternal() {
155			return Version{}, ErrAccessDenied
156		}
157		if strings.TrimSpace(content) == "" {
158			return Version{}, fmt.Errorf("%w: corrected content is required", ErrInvalidArgument)
