167		// UTF-8：坏字节位于开头、中间、结尾，或最后一个多字节字符没有写完整，
168		// 都在此拒绝，不能让 JSON 落盘把原因替换成 U+FFFD 导致重开后同一版本
169		// 的解释与提交时不同，也不能只保存其中合法的部分。即使用户同时写了可读
170		// 的中文说明也一样拒绝。用户明确输入的合法 U+FFFD 字符本身是合法
171		// UTF-8，不受此限制。
172		if !validContent(reason) {
173			return Version{}, fmt.Errorf("%w: correction reason must be valid UTF-8", ErrInvalidArgument)
174		}
175		if expectedCurrentVersion <= 0 {
176			return Version{}, fmt.Errorf("%w: expected current version must be positive", ErrInvalidArgument)
177		}
178	
179		var result Version
180		err := s.mutate(func(snap *snapshot) error {
181			r := snap.Records[recordID]
182			if r == nil {
183				return fmt.Errorf("%w: record %q", ErrNotFound, recordID)
184			}
185			if _, err := requireActivePatient(snap, r.PatientID); err != nil {
186				return err
187			}
188			if r.CurrentVersionID == "" {
189				return fmt.Errorf("%w: record %q has no effective version; activate its draft first", ErrInvalidArgument, recordID)
190			}
191			current := snap.Versions[r.CurrentVersionID]
192			if current == nil {
193				// 内部状态不应出现；按不存在处理，拒绝写入。
194				return fmt.Errorf("%w: current version %q", ErrNotFound, r.CurrentVersionID)
195			}
196			if current.Number != expectedCurrentVersion {
197				return fmt.Errorf("%w: record %q is at version %d, not %d",
198					ErrConflict, recordID, current.Number, expectedCurrentVersion)
199			}
200	
201			now := s.now()
202			v := &Version{
203				ID:        newID("ver"),
204				RecordID:  r.ID,
205				Number:    current.Number + 1,
206				Content:   content,
207				Category:  r.Category,
208				CreatedAt: now,
209				PrevID:    current.ID,
210				Reason:    reason,
211			}
212			snap.Versions[v.ID] = v
213			r.CurrentVersionID = v.ID
214			r.Versions = append(r.Versions, v.ID)
215			s.addAudit(snap, r.PatientID, actor, ActionCorrected, "record", r.ID, now)
216			result = *v
217			return nil
218		})
219		return result, err
220	}
221	
222	// requireDraftRecord 取出仍处于草稿阶段（有草稿且尚无生效版本）的记录。
223	func requireDraftRecord(snap *snapshot, recordID ID) (*Record, error) {
224		r := snap.Records[recordID]
225		if r == nil {
226			return nil, fmt.Errorf("%w: record %q", ErrNotFound, recordID)
227		}
228		if r.CurrentVersionID != "" || !r.HasDraft {
229			return nil, fmt.Errorf("%w: record %q is already effective", ErrActive, recordID)
230		}
231		return r, nil
232	}
